class Multigo{constructor(blockId,key=""){this.key=key;this.blockId=blockId;this.block=document.querySelector(`#${this.blockId}`);if(this.block!==null){this.load()}}load(){loadExternalScript(`https://tapi.multigo.ru/locator/api/js?divId=${this.blockId}&key=${this.key}&staticLoc=&mapZoom=12`).then(resolve=>{}).catch(error=>{console.error("Ошибка при загрузке внешнего скрипта:",error)})}}